/**
 * REPORTING DTOs for Analytics/AI Module
 *
 * Reports are generated by consuming LOCKED (approved) attendance records
 * Owned by: Ayodeji Shorunmu (Data Engineer)
 *
 * Data Source: attendance_record (only status = 'LOCKED')
 * Refresh Rate: Varies by report (see each DTO)
 * Export Formats: CSV, PDF, JSON
 */

export interface DailyAttendanceSummaryDTO {
  date: string; // ISO date
  branches: BranchAttendanceDTO[];
  totalPresent: number;
  totalAbsent: number;
  totalLate: number;
  totalEmployees: number;
  attendanceRate: number; // percentage
  refreshedAt: Date;
}

export interface BranchAttendanceDTO {
  branchCode: string;
  branchName: string;
  present: number;
  absent: number;
  late: number;
  total: number;
  attendanceRate: number;
  // Drill-down capability
  employeeDetails?: EmployeeAttendanceStatusDTO[];
}

export interface EmployeeAttendanceStatusDTO {
  employeeId: number;
  employeeName: string;
  employeeCode: string;
  status: 'PRESENT' | 'ABSENT' | 'LATE' | 'ON_LEAVE';
  checkIn?: Date;
  checkOut?: Date;
  lateMinutes?: number;
  department?: string;
  shiftName?: string;
}

export interface MonthlyAttendanceReportDTO {
  employeeId: number;
  employeeName: string;
  employeeCode: string;
  department: string;
  period: string; // YYYY-MM
  workingDays: number; // scheduled working days in month
  daysPresent: number;
  daysAbsent: number;
  daysLate: number;
  daysOnLeave?: number;
  totalHours: number; // total worked hours
  totalOvertimeHours: number;
  totalUndertimeHours: number;
  approvedHours: number; // hours approved after corrections
  attendanceRate: number; // (daysPresent / workingDays) * 100
  fraudFlagsCount: number; // count of fraud flags in period
  correctionRequestsCount: number;
  crossBranchEventsCount: number;
  dailyRecords: DailyRecordSummaryDTO[];
  generatedAt: Date;
}

export interface DailyRecordSummaryDTO {
  date: string; // ISO date
  dayOfWeek: string; // Monday, Tuesday, etc.
  status: 'PRESENT' | 'ABSENT' | 'LATE' | 'ON_LEAVE';
  checkIn?: string;
  checkOut?: string;
  hoursWorked?: number;
  overtimeHours?: number;
  undertimeHours?: number;
  lateMinutes?: number;
  shiftName?: string;
  isCrossBranch?: boolean;
  hasFraudFlags?: boolean;
  notes?: string;
}

export interface OvertimeReportDTO {
  period: string; // YYYY-MM or YYYY
  overtimeByEmployee: OvertimeEmployeeDTO[];
  overtimeByDepartment: OvertimeDepartmentDTO[];
  totalOvertimeHours: number;
  totalEmployeesWithOvertime: number;
  averageOvertimePerEmployee: number;
  thresholdAlerts: OvertimeThresholdAlertDTO[];
  costImpactEstimate?: {
    totalAmount: number;
    currency: string;
    rateUsed: number; // OT multiplier (e.g., 1.5x)
    note: string;
  };
  generatedAt: Date;
}

export interface OvertimeEmployeeDTO {
  employeeId: number;
  employeeName: string;
  employeeCode: string;
  department: string;
  totalOvertimeHours: number;
  overtimeDays: number;
  averagePerDay: number;
  maxSingleDay: number;
  costEstimate?: number;
}

export interface OvertimeDepartmentDTO {
  departmentName: string;
  totalOvertimeHours: number;
  employeeCount: number;
  averagePerEmployee: number;
  topEmployee?: string;
  costEstimate?: number;
}

export interface OvertimeThresholdAlertDTO {
  employeeId: number;
  employeeName: string;
  department: string;
  overtimeHours: number;
  thresholdHours: number; // configured limit
  percentageOverThreshold: number;
  alertLevel: 'WARNING' | 'CRITICAL'; // WARNING if 100-150% of threshold, CRITICAL if >150%
  consecutiveDaysOverLimit: number;
}

export interface AbsenteeismAnalysisDTO {
  period: string; // YYYY-MM or YYYY
  departments: AbsenteeismDepartmentDTO[];
  overallAbsenteeismRate: number; // percentage
  patternAnalysis: AbsenteeismPatternDTO;
  topAbsentees: AbsenteeEmployeeDTO[];
  performanceKPIImpact?: {
    departmentsAtRisk: string[]; // dept names
    employeesAtRisk: number[]; // employee IDs
    recommendedActions: string[];
  };
  generatedAt: string;
}

export interface AbsenteeismDepartmentDTO {
  departmentName: string;
  totalAbsences: number;
  absenteeismRate: number; // %
  trend: 'UP' | 'STABLE' | 'DOWN'; // compared to previous period
  trendPercent: number; // % change from previous period
  topAbsentee?: string;
  monthlyBreakdown?: {
    [key: string]: number; // YYYY-MM-DD: absence count
  };
}

export interface AbsenteeismPatternDTO {
  mondayAbsenteeismRate: number;
  fridayAbsenteeismRate: number;
  weekendFollowingAbsentees: number; // absences on Mon/Fri followed by weekend
  secondHalfOfMonthRate: number; // absences in days 16-31
  detectedPatterns: string[]; // e.g., "Monday spike", "End-of-month trend"
  suspiciousEmployees: number[]; // IDs with statistical anomalies
}

export interface AbsenteeEmployeeDTO {
  employeeId: number;
  employeeName: string;
  department: string;
  totalAbsences: number;
  absenteeismRate: number;
  consecutiveAbsences: number; // longest streak
  lastAbsenceDate: string; // ISO date
}

export interface ScheduleComplianceReportDTO {
  period: string; // YYYY-MM
  employeeCompliance: ScheduleComplianceEmployeeDTO[];
  departmentAverage: number; // % compliance
  deviationsByReason: {
    [reason: string]: number; // LATE, EARLY_DEPARTURE, ABSENT, etc.
  };
  generatedAt: string;
}

export interface ScheduleComplianceEmployeeDTO {
  employeeId: number;
  employeeName: string;
  department: string;
  scheduleReferenceId: number;
  shiftName: string;
  plannedHours: number;
  actualHours: number;
  complianceRate: number; // (actualHours / plannedHours) * 100
  deviationScore: number; // 0-100, 0=perfect, 100=completely non-compliant
  deviationDetails: {
    lateArrivals: number;
    earlyDepartures: number;
    absences: number;
    avgLateMinutes: number;
    avgEarlyMinutes: number;
  };
  usedInPerformanceReview?: boolean;
}

export interface CrossBranchActivityReportDTO {
  period: string; // YYYY-MM
  totalCrossBranchEvents: number;
  approvalRate: number; // % of approved / total
  eventsByBranch: CrossBranchBranchDTO[];
  frequentRoutes: CrossBranchRouteDTO[];
  employeeFrequency: CrossBranchEmployeeDTO[];
  capacityPlanningInsights?: {
    highTrafficBranches: string[]; // branch codes
    recommendedHiringBranches: string[];
    recommendedCapacityIncreases: { [branchCode: string]: number }; // headcount
  };
  generatedAt: string;
}

export interface CrossBranchBranchDTO {
  homeBranchCode: string;
  homeBranchName: string;
  visitorBranches: {
    [branchCode: string]: number; // branch code: visit count
  };
  totalOutgoing: number;
  totalIncoming: number;
}

export interface CrossBranchRouteDTO {
  fromBranch: string; // home branch
  toBranch: string; // visited branch
  frequency: number; // count of cross-branch events
  approvalRate: number; // %
  lastEvent: string; // ISO timestamp
}

export interface CrossBranchEmployeeDTO {
  employeeId: number;
  employeeName: string;
  homeBranch: string;
  totalCrossBranchEvents: number;
  frequentlyVisitedBranches: {
    [branchCode: string]: number; // branch code: visit count
  };
  approvalRate: number; // %
}

export interface ReportExportDTO {
  reportType: 'DAILY' | 'MONTHLY' | 'OVERTIME' | 'ABSENTEEISM' | 'COMPLIANCE' | 'CROSS_BRANCH';
  format: 'JSON' | 'CSV' | 'PDF';
  data: any; // the actual report DTO
  filename: string;
  generatedAt: string;
  generatedBy: string; // user ID or system
}

export interface ReportingMetadataDTO {
  lastRefreshTime: {
    daily: string;
    monthly: string;
    overtime: string;
    absenteeism: string;
    compliance: string;
    crossBranch: string;
  };
  refreshIntervals: {
    daily: number; // minutes
    monthly: number; // days
    overtime: number;
    absenteeism: number;
    compliance: number;
    crossBranch: number;
  };
  dataQuality: {
    lockedRecordsCount: number;
    pendingRecordsCount: number;
    fraudFlagsCount: number;
    correctionRequestsCount: number;
  };
}
